import { promises as fs } from 'fs';
import path from 'path';

// Server-side (fs) loader for public/data/province-geography.json — neighbors (with cardinal
// direction) + coastline, generated by scripts/generate-province-geography.mjs from province geometry.

export type Direction = 'N' | 'NE' | 'E' | 'SE' | 'S' | 'SW' | 'W' | 'NW';
export type CountryCode = 'CN' | 'LA' | 'KH';

export interface ProvinceBorder {
  country: CountryCode;
  direction: Direction;
  km: number;
}

export interface ProvinceGeographyEntry {
  neighbors: { slug: string; direction: Direction }[];
  hasCoastline: boolean;
  coastlineKm: number; // official figure (post = curated; pre = geometry-proportioned split)
  coastlineGeomKm?: number; // raw OSM-geometry length (mainland), cross-check only
  borders?: ProvinceBorder[];
}

interface ProvinceGeographyFile {
  pre: Record<string, ProvinceGeographyEntry>;
  post: Record<string, ProvinceGeographyEntry>;
}

let cache: ProvinceGeographyFile | null = null;

async function load(): Promise<ProvinceGeographyFile> {
  if (!cache) {
    const filePath = path.join(process.cwd(), 'public/data/province-geography.json');
    cache = JSON.parse(await fs.readFile(filePath, 'utf-8')) as ProvinceGeographyFile;
  }
  return cache;
}

export async function getProvinceGeography(
  mode: 'pre' | 'post',
  slug: string,
): Promise<ProvinceGeographyEntry | null> {
  const data = await load();
  return data[mode]?.[slug] ?? null;
}
